/**
 * Shared client for the `hashroll` Solana program (used by the API, the web app and the tests).
 * The IDL in ./idl is generated by `npm run build:program`; do not edit it by hand.
 */
import { Buffer } from "buffer";
import BNImpl from "bn.js";
import { BorshCoder, EventParser, Program, type Provider } from "@coral-xyz/anchor";
import { Connection, PublicKey } from "@solana/web3.js";
import { getAssociatedTokenAddressSync } from "@solana/spl-token";
import idlJson from "./idl/hashroll.json" with { type: "json" };
import type { Hashroll } from "./idl/hashroll.js";

export type { Hashroll };
/**
 * BN (bn.js) is what @coral-xyz/anchor uses for u64/i64. It is imported from bn.js directly because
 * Node's CommonJS interop does not expose `BN` as a named export of @coral-xyz/anchor.
 */
export const BN = BNImpl;
export type BN = BNImpl;

export const IDL = idlJson as unknown as Hashroll;
export const PROGRAM_ID = new PublicKey(IDL.address);

/** BPF upgradeable loader (not exported by @solana/web3.js v1). */
export const BPF_LOADER_UPGRADEABLE_ID = new PublicKey("BPFLoaderUpgradeab1e11111111111111111111111");

/** ProgramData account of the program, whose upgrade authority `initialize` checks. */
export function programDataAddress(programId = PROGRAM_ID): PublicKey {
  return PublicKey.findProgramAddressSync([programId.toBuffer()], BPF_LOADER_UPGRADEABLE_ID)[0];
}

/** HROLL is an SPL token with 9 decimals; every amount is an integer in base units (u64). */
export const HROLL_DECIMALS = 9;
export const HROLL_UNIT = 10n ** BigInt(HROLL_DECIMALS);

/** Byte offset of `PlayerState.pending` (discriminator 8 + player 32 + nonce 8 + commitment 32). */
export const PENDING_OFFSET = 80;

export type Direction = "under" | "over";

/* --------------------------------------------------------------- addresses */

export function configPda(programId = PROGRAM_ID): PublicKey {
  return PublicKey.findProgramAddressSync([Buffer.from("config")], programId)[0];
}

export function vaultPda(programId = PROGRAM_ID): PublicKey {
  return PublicKey.findProgramAddressSync([Buffer.from("vault")], programId)[0];
}

export function playerPda(player: PublicKey, programId = PROGRAM_ID): PublicKey {
  return PublicKey.findProgramAddressSync([Buffer.from("player"), player.toBuffer()], programId)[0];
}

export function playerTokenAccount(mint: PublicKey, player: PublicKey): PublicKey {
  return getAssociatedTokenAddressSync(mint, player);
}

/** Validates a base58 wallet address. Base58 is case-sensitive: never lowercase it. */
export function parsePublicKey(value: string): PublicKey | null {
  try {
    const key = new PublicKey(value);
    return key.toBase58() === value ? key : null;
  } catch {
    return null;
  }
}

/* ----------------------------------------------------------------- program */

export function getProgram(provider: Provider): Program<Hashroll> {
  return new Program<Hashroll>(IDL, provider);
}

/** Read-only program instance (fetch accounts, build instructions); cannot sign. */
export function readOnlyProgram(connection: Connection): Program<Hashroll> {
  return new Program<Hashroll>(IDL, { connection } as Provider);
}

export const toAnchorDirection = (d: Direction) => (d === "over" ? { over: {} } : { under: {} });
export const fromAnchorDirection = (d: object): Direction => ("over" in d ? "over" : "under");

/* --------------------------------------------------------------- formatting */

export function toHex(bytes: ArrayLike<number>): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
}

export function fromHex(hex: string): number[] {
  if (!/^[0-9a-fA-F]{64}$/.test(hex)) throw new Error("expected 32 bytes of hex");
  return Array.from({ length: 32 }, (_, i) => parseInt(hex.slice(i * 2, i * 2 + 2), 16));
}

export const isZeroCommitment = (c: ArrayLike<number>) => Array.from(c).every((b) => b === 0);

export function formatHroll(units: bigint, maxFraction = 4): string {
  const neg = units < 0n;
  const abs = neg ? -units : units;
  const whole = abs / HROLL_UNIT;
  let frac = (abs % HROLL_UNIT).toString().padStart(HROLL_DECIMALS, "0").slice(0, maxFraction).replace(/0+$/, "");
  return `${neg ? "-" : ""}${whole.toLocaleString("en-US")}${frac ? "." + frac : ""}`;
}

export function parseHroll(value: string): bigint {
  const m = value.trim().match(/^(\d+)(?:\.(\d+))?$/);
  if (!m) throw new Error("invalid amount");
  const frac = m[2] ?? "";
  if (frac.length > HROLL_DECIMALS) throw new Error(`at most ${HROLL_DECIMALS} decimal places`);
  return BigInt(m[1]) * HROLL_UNIT + BigInt(frac.padEnd(HROLL_DECIMALS, "0"));
}

/* ------------------------------------------------------------------- state */

export interface PlayerView {
  player: string;
  nonce: number;
  commitment: string; // hex; all zeros = the house has not committed yet
  pending: boolean;
  bet: null | {
    amount: bigint;
    target: number;
    direction: Direction;
    potentialPayout: bigint;
    placedAt: number; // unix seconds
    clientSeed: string;
  };
}

type PlayerAccount = Awaited<ReturnType<Program<Hashroll>["account"]["playerState"]["fetch"]>>;

export function toPlayerView(a: PlayerAccount): PlayerView {
  return {
    player: a.player.toBase58(),
    nonce: a.nonce.toNumber(),
    commitment: toHex(a.commitment),
    pending: a.pending,
    bet: a.pending
      ? {
          amount: BigInt(a.betAmount.toString()),
          target: a.betTarget,
          direction: fromAnchorDirection(a.betDirection),
          potentialPayout: BigInt(a.betPayout.toString()),
          placedAt: a.betPlacedAt.toNumber(),
          clientSeed: a.betClientSeed,
        }
      : null,
  };
}

export async function fetchPlayer(program: Program<Hashroll>, player: PublicKey): Promise<PlayerView | null> {
  const a = await program.account.playerState.fetchNullable(playerPda(player, program.programId));
  return a ? toPlayerView(a) : null;
}

/* ------------------------------------------------------------------ events */

export interface BetHistoryEntry {
  signature: string;
  blockTime: number | null;
  kind: "settled" | "expired";
  nonce: number;
  commitment: string;
  serverSeed: string | null; // null when the bet expired (seed never revealed)
  clientSeed: string | null;
  amount: bigint | null;
  target: number | null;
  direction: Direction | null;
  roll: number | null;
  win: boolean;
  payout: bigint;
}

const coder = new BorshCoder(IDL);

/** Decodes every Hashroll event in a transaction's log messages. */
export function parseEvents(logs: string[], programId = PROGRAM_ID) {
  return Array.from(new EventParser(programId, coder).parseLogs(logs));
}

const n = (v: { toString(): string }) => Number(v.toString());
const big = (v: { toString(): string }) => BigInt(v.toString());

export function eventsToHistory(signature: string, blockTime: number | null, logs: string[], player: PublicKey, programId = PROGRAM_ID): BetHistoryEntry[] {
  const out: BetHistoryEntry[] = [];
  for (const ev of parseEvents(logs, programId)) {
    const d = ev.data as Record<string, any>;
    if (!(d.player instanceof PublicKey) || !d.player.equals(player)) continue;
    const name = ev.name.toLowerCase();
    if (name === "betsettled") {
      out.push({
        signature, blockTime, kind: "settled",
        nonce: n(d.nonce), commitment: toHex(d.commitment),
        // Anchor's event coder keeps the IDL's snake_case field names.
        serverSeed: d.server_seed, clientSeed: d.client_seed,
        amount: big(d.amount), target: d.target, direction: fromAnchorDirection(d.direction),
        roll: d.roll, win: d.win, payout: big(d.payout),
      });
    } else if (name === "betexpired") {
      out.push({
        signature, blockTime, kind: "expired",
        nonce: n(d.nonce), commitment: toHex(d.commitment),
        serverSeed: null, clientSeed: null, amount: null, target: null, direction: null, roll: null,
        win: true, payout: big(d.payout),
      });
    }
  }
  return out;
}

/** Reads the player's resolved bets straight from the chain (transactions touching the player PDA). */
export async function fetchBetHistory(connection: Connection, player: PublicKey, limit = 25, programId = PROGRAM_ID): Promise<BetHistoryEntry[]> {
  const sigs = await connection.getSignaturesForAddress(playerPda(player, programId), { limit });
  const ok = sigs.filter((s) => !s.err);
  if (ok.length === 0) return [];
  const txs = await connection.getTransactions(ok.map((s) => s.signature), { maxSupportedTransactionVersion: 0, commitment: "confirmed" });
  const out: BetHistoryEntry[] = [];
  txs.forEach((tx, i) => {
    const logs = tx?.meta?.logMessages;
    if (logs) out.push(...eventsToHistory(ok[i].signature, tx.blockTime ?? null, logs, player, programId));
  });
  return out.sort((a, b) => b.nonce - a.nonce);
}
